    display: none;\n}\n\n#manage_users #availableList .icon.button,\n#manage_users #assignedList .icon.button,\n#manage_roles #availableList .icon.button,\n#manage_roles #assignedList .icon.button {\n    display: none;\n}\n\n#manage_users #availableList .wrap.button,\n#manage_users #assignedList .wrap.button,\n#manage_roles #availableList .wrap.button,\n#manage_roles #assignedList .wrap.button {\n    padding-left: 10px;\n}\n\n#manage_orgs #properties,\n#manage_users #properties {\n    min-width: 420px;\n}\n\n/* fix to Properties panel / Horizontal scroll bar not showing on IE (see bug 45034)*/\n@media screen\\0 {\n    .column.tertiary .node {\n        overflow: visible;\n    }\n}\n\n@media all and (-ms-high-contrast: none), (-ms-high-contrast: active) {\n    .column.tertiary .node {\n        overflow: visible;\n    }\n}\n/* --------- */\n/*  END 14.  */\n/* --------- */\n\n\n\n/* -------------------------------------------- */\n/*  START 15. MESSAGES, LIST & DETAIL PAGES     */\n/* -------------------------------------------- */\n#messageDetail .column.showingToolBar .message {\n    margin: 32px 64px;\n}\n\n#messages .subheader {\n    height: auto;\n}\n\n#messageList .leaf .wrap,\n#messageListHeader .leaf p,\n#messageDetail .message .label .wrap {\n    color: #666666;\n}\n\n#messageList .leaf.selected .column p {\n    color: #ffffff;\n}\n\n#messages #display > .column.decorated.primary,\n#messageDetail #display > .column.decorated.primary {\n    top: 40px;\n}\n\n#messages .toolbar,\n#messageDetail .toolbar {\n    border-top: none;\n    display: flex;\n    padding: 0 5px 0 0;\n    justify-content: space-between;\n    align-items: center;\n}\n\n#messages .toolbar .button.capsule.text .wrap,\n#messageDetail .toolbar .button.capsule.text .wrap {\n    line-height: 32px;\n}\n\n#messages .column.decorated > .content > .body {\n    margin-top: 0;\n    top: 65px;\n}\n\n#messageDetail .column.decorated > .content > .body {\n    margin-top: 2px;\n    top: 32px;\n}\n\n#messageDetail .message,\n#messageDetail .message .label .wrap {\n    font-family: source_sans_proregular, Franklin Gothic, Verdana, Arial, sans-serif;\n    font-size: 13px;\n    line-height: 18px;\n}\n\n#messageDetail .message .label {\n    font-family: source_sans_probold, Franklin Gothic Medium, Arial Black;\n}\n/* --------- */\n/*  END 15.  */\n/* --------- */\n\n\n\n/* ------------------------- */\n/*  START 16. MULTI-SELECT   */\n/* ------------------------- */\n.mSelect {\n    box-sizing: border-box;\n    width: 100%;\n    background: transparent;\n    min-width: 220px; /* need this so close button will fit into footer */\n}\n\n.topOfPage .msPlaceholder > div {\n    width: 220px;\n}\n\n.mSelect-input,\ninput[type=\"text\"].mSelect-input {\n    background: #fff url(\"images/panels_icons_sprite.png\") no-repeat;\n    border-style: solid;\n    background-position: right -325px;\n    box-sizing: border-box;\n    margin: 4px 0 0 0;\n    padding: 0 22px 0 3px;\n    width: 100%;\n}\n\n.mSelect-input.placeholder {\n    color: #999;\n}\n\n.mSelect-list {\n    box-sizing: border-box;\n    width: 100%;\n    margin: 0;\n    position: relative;\n}\n\n.mSelect-list > li {\n    line-height: 17px;\n    padding: 0 0 0 4px;\n    cursor: pointer;\n    white-space: nowrap;\n}\n\n.mSelect-listContainer {\n    width: 100%;\n}\n\n.mSelect-listContainer > .sList {\n    border: 1px solid silver;\n    border-top: none;\n}\n\n.mSelect-avList li {}\n\n.mSelect-avList li.selected {\n    background-image: url(\"images/panels_icons_sprite.png\");\n    background-repeat: no-repeat;\n    background-position: right -34px;\n    padding-right: 26px;\n    color: #fff;\n}\n\n.mSelect-avList li a {\n    text-decoration: none;\n    display: block;\n    overflow: hidden;\n    width: 100%;\n}\n\n.mSelect-svListPlaceholder {\n    margin-top: 5px;\n    background-color: #ffffff;\n}\n\n.mSelect-svListPlaceholder.focused .sList {}\n\n.mSelect-svList > .selected .mSelect-svList-button {\n    background-position: right -236px;\n}\n\n.mSelect-svListPlaceholder .sList {\n    max-height: inherit;\n    height: 100%;\n    min-height: 60px;\n    border: 1px solid silver;\n}\n\n.mSelect-svList li a {\n    display: inline-block;\n    padding-right: 24px;\n    width: 100%;\n    text-decoration: none;\n    box-sizing: border-box;\n}\n\n.mSelect-svList-button {\n    float: right;\n    height: 16px;\n    width: 24px;\n    background: url(\"images/panels_icons_sprite.png\") no-repeat;\n    background-position: -1px -75px;\n    background-color: #fff;\n}\n\n.disabled .mSelect-list > li,\n.disabled .mSelect-svList-button,\n.disabled .mSelect-svList li a {\n    cursor: default;\n}\n\n.disabled .mSelect-svList li a:active {\n    color: inherit;\n}\n\n.mSelect-svInput {\n    position: absolute !important;\n    left: -9999px;\n}\n\n.mSelect-footer {\n    box-sizing: border-box;\n    background-color: #fff;\n    width: 100%;\n    height: 18px;\n    border: 1px solid silver;\n    border-top: none;\n    position: relative;\n}\n\n.mSelect-footer input {\n    width: 20px !important;\n    top: 1px !important;\n}\n\n.mSelect-footer-selectOptions {\n    font: normal 11px Verdana, Arial, Helvetica, sans-serif;\n    padding: 0 5px;\n    margin: 3px 0 0 0;\n    color: #666666;\n    line-height: 1em;\n    display: inline-block;\n}\n\n.mSelect-all-label {\n    position: relative;\n}\n\n.mSelect-footer-button {\n    width: auto;\n    height: 100%;\n    padding: 0 12px 1px 12px;\n    margin: 0;\n    border: none;\n    border-left: 1px solid silver;\n    background: url(\"images/button_action_sprite.png\") repeat-x scroll 0 0 #D8DAD7;\n    font-weight: normal;\n    font-size: 11px \\9;\n    color: #333;\n    cursor: pointer;\n    position: absolute;\n    top: 0;\n    right: 0;\n}\n\n.mSelect-footer-trueAll {\n    height: 20px;\n}\n\n.mSelect-footer-trueAll input {\n    width: 13px !important;\n    margin: 3px 0 0 3px;\n}\n\n.mSelect-footer-trueAll .mSelect-footer-selectOptions {\n    padding: 0 8px 0 0;\n    margin: 0;\n    vertical-align: top;\n    height: 18px;\n    line-height: 17px;\n}\n\n.mSelect-all-label {\n    position: relative;\n}\n\n.mSelect-footer-button.over {\n    background-position: 0 -50px;\n}\n\n.mSelect-footer-button.pressed {\n    background-position: 0 -103px;\n    color: #fff;\n}\n\n/* start - iPad */\n.mSelect.ipad .mSelect-input,\n.mSelect.ipad input.mSelect-input[type=\"text\"] {\n    height: 30px;\n    background-position: right -323px;\n}\n\n.mSelect.ipad .mSelect-svList li,\n.mSelect-listContainer.ipad .mSelect-avList li {\n    height: 35px;\n    line-height: 33px;\n}\n\n.mSelect.ipad .mSelect-svList-button {\n    height: 32px;\n    background-position: -1px -192px;\n}\n\n.mSelect.ipad .selected .mSelect-svList-button {\n    background-position: -1px -270px;\n}\n\n.mSelect-listContainer.ipad .mSelect-avList li.selected {\n    background-position: right -150px;\n}\n\n.mSelect-listContainer.ipad .mSelect-footer {\n    height: 30px;\n    line-height: 30px;\n    margin-right: 8px;\n}\n\n.mSelect-listContainer.ipad .mSelect-footer-selectOptions {\n    height: 30px;\n}\n\n.mSelect-listContainer.ipad .mSelect-footer-button {\n    height: 100%;\n}\n\n.mSelect-listContainer.ipad > .sList {\n    max-height: 90px;\n}\n/* END iPad */\n\n/* for dropdown parts which should be placed in body */\n.mSelect-dropDown {\n    position: absolute;\n    background-color: #FFFFFF;\n    box-shadow: 0 4px 4px rgba(51, 51, 51, 0.5);\n    z-index: 1001;\n}\n/* --------- */\n/*  END 16.  */\n/* --------- */\n\n\n\n/* ---------------------------- */\n/*  START 17. PICK DATA SOURCE  */\n/* ---------------------------- */\n/* can\'t find pickDatasource in UI. Only found in messages_properties\n   files. Are these from legacy domain designer maybe? Commented out Oct 2022.\n#pickDatasource form {\n    padding: 16px\n}\n\n#pickDatasource form .wrap {\n    display: block;\n    padding-bottom: 0;\n    margin-bottom: 6px;\n}\n\n#pickDatasource #datasourceID {\n    width: auto;\n   