rd;\n}\n\n#logSettings .list.threeColumn .wrap .column.three {\n    display: inline-block;\n    width: 15%;\n}\n\n#logSettings .list.threeColumn .wrap .column.three > select {\n    width: auto;\n}\n\n/* importDataFile */\n#importDataFile #fileUploadForm {\n    margin: 24px;\n    width: 400px;\n}\n\n#importDataFile #uploadFile {\n    height: 22px;\n    width: 100%;\n}\n\n#importDataFile .inputSet .leaf > .inputSet .leaf {\n    overflow: hidden;\n    padding: 3px 17px 0 17px;\n}\n\n/* secret key */\n#secretKey .control.radio.twoLine {\n    margin-bottom: 10px;\n}\n\n#secretKey .control.radio.twoLine > .wrap {\n    line-height: 16px;\n}\n\n#secretKey .button.action {\n    top: -1px;\n}\n\n#secretKey .button.action > .wrap {\n    margin-left: 0;\n}\n\n#secretKey .control.twoLine  .control.inline input {\n    margin-top: 2px;\n}\n\n/* exportDataFile */\n#exportDataFile .body div > fieldset {\n    margin: 24px;\n}\n\n#exportDataFile #filenameId {\n    width: 300px;\n}\n\n#selectRolesUsers {\n    margin: 4px;\n    width: 750px;\n    height: 220px;\n    -webkit-user-select: none; /* webkit only */\n}\n\n#selectRolesUsers .selectedRoles {\n    margin-right: 8px;\n}\n\n#selectRolesUsers input[type=text] {\n    height: 20px;\n    width: 320px;\n}\n\n/* TEMPORARY FOR GENERAL SERVER SETTINGS */\n/* Can be deleted after merge with facelift project */\n.generalSettings {\n    padding: 24px;\n}\n\n#serverSettingsMenu {\n    top: 40px;\n}\n\n#settings > .content > .body,\n#logCollectors > .content > .body {\n    top: 40px;\n}\n\n#settings.column.decorated > .content > .body > .title,\n#logCollectors.column.decorated > .content > .body > .title {\n    background-color: var(--background-grey-10);\n    border-bottom: 1px solid var(--border-white);\n    color: var(--theme-medium-dark);\n    font-size: 12px;\n    height: 28px;\n    line-height: 26px;\n    padding-left: 12px;\n    position: relative;\n    white-space: nowrap;\n    z-index: 1;\n}\n\n#settings .pane.settings .control .wrap {\n    color: var(--theme-medium-dark);\n    font-weight: bold;\n}\n\n#settings .pane.settings .control.checkBox .wrap {\n    padding-left: 8px;\n}\n\n#analysisOptions #settings .pane.settings .control.input.text > .wrap,\n#designerOptions #settings .pane.settings .control.input.text > .wrap {\n    align-self: center;\n    line-height: 1.4;\n    margin: 0 0 0 6px;\n}\n\n#settings .pane.settings .control.description {\n    line-height: 1.5;\n}\n\n#settings > .content > .body > .subheader {\n    height: 34px;\n    padding: 2px;\n}\n\n#awsOptions .list.settings .control.input.text {\n    display: flex;\n    flex-direction: column-reverse;\n}\n\n#awsOptions .list.settings .control.input.text + .control.description,\n#designerOptions .list.settings .control.input.text + .control.description{\n    margin-left: 12px;\n    margin-right: 56px;\n}\n\n#awsOptions .pane.settings .control.checkBox + .control.description,\n#analysisOptions .pane.settings .control.checkBox + .control.description,\n#designerOptions .pane.settings .control.checkBox + .control.description {\n    margin-left: 32px;\n    margin-right: 56px;\n}\n\n#analysisOptions .pane.settings .control.input.text,\n#designerOptions .pane.settings .control.input.text {\n    display: flex;\n    margin-bottom: 8px;\n}\n\n#analysisOptions .pane.settings .control.input.text + .control.description,\n#designerOptions .pane.settings .control.input.text + .control.description{\n    margin-left: 64px;\n}\n\n#analysisOptions .pane.settings .control.input.text + .description:not(.control) {\n    margin-left: 114px;\n}\n\n#logSettings .list.js-logSettings > li:first-of-type > .wrap,\n#settings .list.settings > li:first-of-type > .wrap {\n    border-top: none;\n}\n/* END TEMPORARY */\n\n\n/* --------- */\n/*  END 24.  */\n/* --------- */\n\n\n\n/* ---------------------------------- */\n/*  START 25. SERVER & SYSTEM ERRORS  */\n/* ---------------------------------- */\n/* server error */\n#serverError .flow .inputs {\n    min-height: 0;\n}\n\n#serverError #stepDisplay {\n    display: block;\n    margin-left: 160px;\n}\n\n#serverError #frame {\n    min-height: 325px;\n}\n\n#serverError .row.instructions {\n    margin: 100px auto;\n    border: 1px solid var(--border-grey-16);\n    width: 400px;\n}\n\n#serverError .flow .inputs > .primary > .content > .body {\n    bottom: 25px;\n}\n\n#serverError .flow .inputs > .primary > .content > .footer {\n    height: 25px;\n    padding: 0;\n}\n\n#serverError #completeStackTrace p,\n#serverError #errorMessages p {\n    margin-left: 20px;\n}\n\n#serverError #completeStackTrace p {\n    white-space: pre;\n}\n\n#serverError #closeErrorPage.closeIcon {\n    float: right;\n    width: 19px;\n    height: 19px;\n    margin: 5px;\n    background: url(\"images/dialogClose.png\");\n    cursor: pointer;\n}\n\n/* system error */\n#systemError.anonymous .primaryNav,\n#systemError.anonymous #globalSearch,\n#systemError.anonymous #userID,\n#systemError.anonymous #main_logOut {\n    display: none;\n}\n\n#systemError.anonymous #help {\n    border: none;\n}\n/* --------- */\n/*  END 25.  */\n/* --------- */\n\n\n\n/* ---------------------------------- */\n/*  START 26. SETTINGS, AD HOC CACHE  */\n/* ---------------------------------- */\n#designerCache #detail {\n    height: 400px;\n    width: 400px;\n}\n\n#designerCache #detail .data {\n    white-space: pre;\n    margin-left: 5px;\n}\n\n#designerCache.nothingToDisplay .list.tabular.fiveColumn {\n    display: none;\n}\n\n#designerCache .list.tabular > .leaf.header > .wrap > .column {\n    line-height: 1em;\n}\n\n#designerCache .list.tabular > .leaf.header > .wrap > .column > p {\n    margin-bottom: 0;\n}\n\n#designerCache .list.fiveColumn .wrap > .column.one {\n    text-align: center;\n    white-space: nowrap;\n    width: 11%;\n    min-width: 130px;\n}\n\n#designerCache .list.fiveColumn .wrap > .column.two {\n    padding: 0 16px;\n    width: 56%;\n}\n\n.list.fiveColumn.tabular .header .wrap .column.two {\n    margin-left: 8px;\n}\n\n#designerCache .list.fiveColumn .wrap > .column.three {\n    padding: 0 8px;\n    text-align: center;\n    white-space: nowrap;\n    width: 11%;\n}\n\n#designerCache .list.fiveColumn .wrap > .column.four {\n    text-align: center;\n    white-space: nowrap;\n    width: 11%;\n    min-width: 120px;\n}\n\n#designerCache .list.fiveColumn .wrap > .column.five {\n    width: auto;\n}\n\n#designerCache .list.fiveColumn.tabular > .list.header div.wrap {\n    background-color: #edf2f8;\n    height: 28px;\n    padding-top: 0;\n    padding-bottom: 0;\n    padding-left: 10px;\n}\n\n#designerCache .list.fiveColumn.tabular > .list.header div.wrap > .column {\n    line-height: 28px;\n}\n\n#designerCache #sortMode {;\n    top: 4px;\n}\n\n#designerCache .list.fiveColumn.tabular > .list div.wrap {\n    min-width: 1020px;\n    padding-top: 10px;\n    padding-bottom: 12px;\n}\n\n#designerCache .list.fiveColumn .query {\n    line-height: 1.182em;\n    margin-bottom: 5px;\n    max-height: 6em;\n    overflow: hidden;\n    white-space: pre;\n}\n\n#designerCache .list.tabular > .leaf.running {\n    font-style: italic;\n}\n\n#designerCache .list.tabular > .leaf.running > .wrap > .column.one {\n    background-image: url(images/list_node_animation.gif);\n    background-repeat: no-repeat;\n    height: 16px;\n}\n/* --------- */\n/*  END 26.  */\n/* --------- */\n\n\n\n/* ------------------------- */\n/*  START 27. SINGLE SELECT  */\n/* ------------------------- */\n/* I\'m not sure if we use sSelect any more */\n.sSelect {\n    position: relative;\n    display: inline-block;\n    -moz-box-sizing: border-box;\n    -ms-box-sizing: border-box;\n    -webkit-box-sizing: border-box;\n    -khtml-box-sizing: border-box;\n    box-sizing: border-box;\n    width: 100%;\n}\n\n.topOfPage .sSelect {\n    width: 220px;\n}\n\n.sSelect.collapsed > .sSelect-listContainer {\n    /* do not hide component because of IE bug with keeping scroll position */\n    left: -9999px;\n}\n\n.sSelect-input {\n    background-color: #ffffff;\n    background-clip: padding-box;\n    -moz-background-clip: padding;\n    -webkit-background-clip: padding-box;\n    -moz-box-sizing: border-box;\n    -ms-box-sizing: border-box;\n    -webkit-box-sizing: border-box;\n    -khtml-box-sizing: border-box;\n    box-sizing: border-box;\n    color: #333333 !important;\n    display: block;\n    height: 26px;\n    line-height: 24px;\n    margin-top: 4px;\n    overflow: hidden;\n    padding: 0 0 0 8px;\n    position: relative;\n    text-decoration: none;\n}\n\n.sSelect-input:hover {\n    text-decoration: none;\n}\n\n.sSelect-input:active {\n    color: #333333;\n}\n\n.sSelect-input > span {\n    white-space: nowrap;\n}\n\n.sSelect.collapsed.focused .sSelect-input {\n    border: 1px solid #fabc58;\n}\n\n.sSelect.expanded .sSelect-input {\n    border-bottom: 0;\n}\n\n.sSelect-disclosureContainer {\n    display: block;\n    position: absolute;\n    top: 0;\n    right: 0;\n    bottom: 0;\n    width: 20px;\n}\n\n.sSelect-disclosure {\n    display: block;\n    height: 100%;\n    width: 100%;\n    background: #fff no-repeat;\n}\n\n.sSelect.expanded .sSelect-disclosure {}\n\n.sSelect.collapsed .sSelect-disclosure {\n    background-image: url(\"images/panels_icons_sprite.png\");\n    background-position: -5px -325px;\n}\n\n.sSelect .control.searchLockup > .button.search {\n    background-image: url(images/panels_icons_sprite.png);\n    background-position: 0 -326px\n}\n\n.sSelect-listContainer {\n    -moz-box-sizing: border-box;\n    -ms-box-sizing: border-box;\n    -webkit-box-sizing: border-box;\n    -khtml-box-sizing: border-box;\n    box-sizing: border-box;\n    border: 1px solid #aaa;\n    border-top: 0;\n    border-bottom: 0;\n    background: #fff;\n    width: 100%;\n    position: absolute;\n    z-index: 1001;\n}\n\n/* start - iPad */\n.sSelect.ipad .sSelect-input,\n.sSelect.ipad input.sSelect-input[type=\"text\"] {\n    height: 30px;\n    line-height: 26px;\n    background-position: right -117px;\n}\n\n.sSelect.ipad .sSelect-disclosureContainer {\n    width: 20px;\n}\n\n.sSelect.ipad.collapsed .sSelect-disclosure {\n    background-position: -5px -323px;\n}\n\n.sSelect.ipad.expanded .sSelect-disclosure {\n}\n\n.sSelect.ipad .control.searchLockup > .wrap,\n.sSelect.ipad .control.searchLockup > .wrap > input[type=\"text\"] {\n    height: 24px;\n}\n\n.sSelect.ipad .control.searchLockup .button.search {\n    height: 25px;\n    background-position: 0 -325px\n}\n\n.sSelect-dropDown.ipad .sSelect-list li {\n    height: 35px;\n    line-height: 35px;\n}\n/* end - iPad */\n\n.sSelect-sSearch {\n    position: relative;\n    z-index: 1010;\n    white-space: nowrap;\n    padding: 3px 4px;\n    margin: 0 0 2px 0;\n    border-top: 1px solid #ececec;\n}\n\n.sSelect .searchLockup {\n    float: none;\n    width: auto;\n    margin: 1px 0;\n}\n\n.sSelect .control.searchLockup > .wrap {\n    background-color: #FFFFFF !important;\n}\n\n.sSelect .control.searchLockup > .button.search {\n    border-left: 0 !important;\n}\n\n.sSelect .control.searchLockup > .wrap > input[type=\"text\"] {\n    -moz-box-sizing: border-box;\n    -ms-box-sizing: border-box;\n    -webkit-box-sizing: border-box;\n    -khtml-box-sizing: border-box;\n    box-sizing: border-box;\n    height: 100%;\n    padding-right: 28px;\n    width: 100%;\n}\n\n.sSelect-list {\n    margin: 0;\n    padding: 0;\n    position: relative;\n}\n\n.sSelect-list li {\n    cursor: pointer;\n    line-height: 16px;\n    padding: 0 6px;\n    white-space: nowrap;\n}\n\n.sSelect-list li a {\n    text-decoration: none;\n}\n\n.sSelect-dropDown {\n    position: absolute;\n    background-color: #FFFFFF;\n    z-index: 1001;\n    -moz-box-shadow: 0 4px 4px rgba(51, 51, 51, 0.5);\n    -webkit-box-shadow: 0 4px 4px rgba(51, 51, 51, 0.5);\n    box-shadow: 0 4px 4px rgba(51, 51, 51, 0.5);\n\n    /* border */\n    box-sizing: border-box;\n    border: 1px solid #aaa;\n    border-top: 0;\n}\n\n.sSelect-dropDown .sList {\n    border: 0;\n}\n\n/* special width requirements to match other input controls */\n.list.inputControls .ssPlaceholder,\n.list.inputControls .msPlaceholder {\n    width: 100%;\n}\n\n.msPlaceholder:disabled,\n.msPlaceholder[disabled] {\n    opacity: .4;\n}\n\n.topOfPage .ssPlaceholder > div {\n    min-width: 220px;\n}\n/* --------- */\n/*  END 27.  */\n/* --------- */\n\n\n\n/* ---------------------------- */\n/*             ???              */\n/* ---------------------------- */\n.disableCursor a {\n    cursor: default;\n}\n\n.disableCursor a:hover {\n    text-decoration: none;\n}\n/* --------- */\n/*  END ???  */\n/* --------- */\n','css',NULL),(20,'/*\n * Copyright (C) 2005 - 2022 TIBCO Software Inc. All rights reserved.\n * http://www.jaspersoft.com.\n *\n * Unless you have purchased a commercial license agreement from Jaspersoft,\n * the following license terms apply:\n *\n * This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU Affero General Public License as\n * published by the Free Software Foundation, either version 3 of the\n * License, or (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE. See the\n * GNU Affero General Public License for more details.\n *\n * You should have received a copy of the GNU Affero General Public License\n * along with this program. If not, see <http://www.gnu.org/licenses/>.\n */\n\n/*  --------------------------------------\n    Pagination control used in Dashboard\n    --------------------------------------\n    File last modified Oct 12, 2022\n    --------------------------------------  */\n\n.paginationControlWrapper {\n    background-color: var(--background-white);\n    height: 36px;\n    padding-top: 8px;\n    padding-right: 8px;\n    padding-left: 8px;\n}\n\n.paginationControl {\n    border-collapse: collapse;\n    border-spacing: 0;\n    height: 28px;\n    margin: 0;\n    max-width: 318px;\n    min-width: 200px;\n    padding: 0;\n    width: auto;\n}\n\n.paginationControl td {\n    height: 28px;\n    line-height: 0;\n    text-align: center;\n    vertical-align: middle;\n    width: 32px;\n}\n\n.paginationControl button {\n    background: none;\n    border: 0;\n    cursor: pointer;\n    display: inline-block;\n    height: 28px;\n    margin: 0;\n    padding: 0;\n    position: relative;\n    width: 28px;\n    outline: 0;\n}\n\n.paginationControl button .wrap {\n    background: rgba(0, 0, 0, 0) none scroll;\n    border: 0;\n    cursor: auto;\n    display: inline;\n    height: auto;\n    margin: 0;\n    padding: 0;\n    width: auto;\n}\n\n.paginationControl button .wrap .icon {\n    background-color: rgba(0, 0, 0, 0);\n    background-image: url(images/button_action_icons_sprite@1x.png);\n    background-repeat: no-repeat;\n    background-size: 240px;\n    border: 0;\n    display: block;\n    height: 24px;\n    left: 0;\n    margin: 0;\n    padding: 0;\n    position: absolute;\n    top: 0;\n    width: 24px;\n    zoom: 1;\n    cursor: pointer;\n}\n\n/* 2x icons */\n@media (-webkit-min-device-pixel-ratio: 2),(min-resolution: 192dpi){\n    .paginationControl > tbody > tr > td > button > .wrap > .icon {\n        background-image: url(images/button_action_icons_sprite@2x.png);\n    }\n}\n\n/* icon positions */\n.paginationControl > tbody > tr > td > button.toLeft > .wrap > .icon {\n    background-position: 0 -116px;\n}\n\n.paginationControl > tbody > tr > td > button.left > .wrap > .icon {\n    background-position: 0 4px;\n}\n\n.paginationControl > tbody > tr > td > button.right > .wrap > .icon {\n    background-position: 2px -26px;\n}\n\n.paginationControl > tbody > tr > td > button.toRight > .wrap > .icon {\n    background-position: 2px -146px;\n}\n\n.paginationControl .currentPageCell {\n    line-height: 28px;\n    min-width: 104px;\n    max-width: 165px;\n    white-space: nowrap;\n    width: 52%;\n}\n\n.paginationControl .currentPageCell .wrap {\n    padding: 0 5px;\n}\n\n.paginationControl .currentPageCell .current {\n    cursor: auto;\n    display: inline-block;\n    height: 22px;\n    line-height: 13px;\n    margin: 0 0 -3px;\n    padding: 2px 3px;\n    white-space: nowrap;\n    width: 50px;\n}\n\n/* States */\n.paginationControl > tbody > tr > td > button:active > .wrap > .icon {\n    opacity: .7;\n}\n\n.paginationControl > tbody > tr > td > button[disabled] > .wrap > .icon {\n    cursor: default;\n    opacity: .4;\n}','css',NULL),(21,'/*\n * Copyright (C) 2005 - 2023 TIBCO Software Inc. All rights reserved.\n * http://www.jaspersoft.com.\n *\n * Unless you have purchased a commercial license agreement from Jaspersoft,\n * the following license terms apply:\n *\n * This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU Affero General Public License as\n * published by the Free Software Foundation, either version 3 of the\n * License, or (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE. See the\n * GNU Affero General Public License for more details.\n *\n * You should have received a copy of the GNU Affero General Public License\n * along with this program. If not, see <http://www.gnu.org/licenses/>.\n */\n\n/* ----------------------------------\n   TABLE OF CONTENTS\n\n    1. BASIC PANEL\n\n    2. TOOLTIP PANEL\n\n    3. INFO PANEL\n\n    4. INFO, SYSTEM PANEL\n\n    5. NOTHING TO DISPLAY\n\n    6. MISC PANEL CONTENT\n\n  -----------------------------------\n    File last modified Jan 30, 2023\n  ----------------------------------- */\n\n\n/* ------------------ */\n/*  1. BASIC PANEL    */\n/* ------------------ */\n.panel {\n    background-color: transparent;\n    border: 0;\n    position: static;\n}\n\n.panel > .header {\n    background-color: #e0e0e0; /* will eventually need to change this */\n    border: 0;\n    border-bottom: 1px solid var(--border-grey-29);\n    height: 28px;\n    line-height: 28px;\n    padding: 0;\n    width: 100%;\n}\n\n.panel > .header > .title {\n    display: inline;\n    float: left;\n    line-height: inherit;\n    margin: 0;\n    max-width: 100%;\n    overflow: hidden;\n    padding: 0;\n    position: static;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n    word-wrap: normal;\n}\n\n.panel > .header > .button.mutton {\n    float: right;\n    position: relative;\n}\n\n.panel .footer {\n    border-top: 1px solid var(--border-grey-10);\n}\n\n.panel.noHeader > .content > .header {\n    display: none;\n}\n\n.panel.showingSubHeader > .content > .body {\n    margin-top: 29px;\n}\n\n/* inlay */\n.panel.inlay .column.primary,\n.panel.inlay .column.secondary,\n.panel.inlay .column.tertiary {\n    margin: 0;\n    position: relative;\n    top: auto;\n    left: auto;\n    bottom: auto;\n    right: auto;\n}\n\n.panel.filter.inlay > .content {\n    min-height: 0;\n}\n\n/* collapsible */\n.collapsiblePanel.open > .header > .buttonIconToggle {\n    background-position: -2px -697px;\n    float: left;\n    margin-right: 4px;\n}\n\n.collapsiblePanel.closed > .header > .buttonIconToggle {\n    background-position: -2px -673px;\n    float: left;\n    margin-right: 4px;\n}\n\n/* tabbed */\n.tabbedPanel > .subcontainer > .tabContainer {\n    display: none;\n}\n\n.tabbedPanel > .header > .tabHeaderContainer {\n    clear: none;\n    float: right;\n}\n\n.tabbedPanel > .header > .tabHeaderContainer > button {\n    border: thin solid rgb(16, 13, 58);\n    width: 22px;\n    height: 16px;\n    margin: 3px;\n    background-color: var(--background-grey-04);\n}\n\n.tabbedPanel > .header > .tabHeaderContainer > button.active {\n    border: thin solid red;\n}\n\n\n/* ------------------ */\n/*  2. TOOLTIP PANEL  */\n/* ------------------ */\n.panel.tooltip {\n    background-color: var(--background-white);\n    border: 1px solid var(--border-grey-16);\n    border-radius: 4px;\n    box-shadow: 0 0 5px rgba(34, 25, 25, 0.4);\n    float: left;\n    margin: 0;\n    max-width: 500px;\n    z-index: 1000;\n}\n\n.panel.tooltip .body {\n    position: relative;\n    overflow: hidden;\n}\n\n.panel.tooltip .title {\n    font-family: source_sans_prosemibold, Franklin Gothic Medium, Verdana, Arial, sans-serif;\n    font-size: 14px;\n}\n\n.panel.tooltip .subtitle {}\n\n.panel.tooltip > .content {\n    left: 0;\n    margin: 0;\n    position: relative;\n    top: 0;\n}\n\n.panel.tooltip > .content > .body {\n    line-height: 2em;\n    padding: 10px 14px 0 14px;\n}\n\n.panel.tooltip .message {\n    font-family: source_sans_proregular, Franklin Gothic, Verdana, Arial, sans-serif;\n    font-size: 13px;\n    line-height: 1.455;\n    overflow: visible;\n    white-space: normal;\n}\n\n.panel.tooltip .message:only-child {\n    margin-bottom: 8px;\n}\n\n.panel.tooltip .message.label {\n    color: var(--theme-medium-dark);\n    font-family: source_sans_prosemibold, Franklin Gothic Medium, Verdana, Arial, sans-serif;\n    font-size: 11px;\n    font-weight: normal;\n    margin-bottom: 0;\n}\n\n.panel.tooltip .corner,\n.panel.tooltip .edge {\n    display: none;\n}\n\n/* variation: calc fields and measures */\n.tooltip.calcfield {\n    position: fixed; \n    z-index: 1001; \n    margin: 8px;\n}\n\n.tooltip.calcfield .field {\n    color: #0295bd;\n}\n\n.tooltip.calcfield .measure {\n    color: #5e8c08;\n}\n\n.tooltip.calcfield .title {\n    margin-bottom: 0;\n}\n\n.tooltip.calcfield .subtitle {\n    font-family: source_sans_proregular, Franklin Gothic, Verdana, Arial, sans-serif;\n    font-size: 12px;\n    line-height: 1.4;\n}\n\n.tooltip.calcfield .message.label {\n    color: #444444;\n    font-size: 12px;\n}\n\n.tooltip.calcfield .message {\n    font-size: 12px;\n}\n\n\n/* ----------------- */\n/*  3. INFO PANEL    */\n/* ----------------- */\n.info {\n    clear: both;\n    border: 1px solid var(--border-grey-16);\n    float: left;\n    margin: 2px 5px 20px 2px; /* moves visual top and left to actual */\n    position: relative;\n}\n\n.info.centered_vert.centered_horz {\n    clear: none;\n    float: none;\n    position: absolute;\n}\n\n.info > .content {\n    /* set coordinates to visual (0,0,0,0) of .column.decorated background,\n       as this object used as reference for positioning\n       child objects */\n    left: -1px;\n    margin-bottom: -5px;\n    margin-right: -4px;\n    position: relative;\n    top: -3px;\n}\n\n.info > .content > .header,\n.info > .content > .footer {\n    display: none;\n}\n\n.info .body {\n    position: relative;\n    padding: 10px;\n    overflow: hidden;\n}\n\n.info .column {\n    position: relative;\n    height: 100%;\n}\n\n.info .body.twoColumn_equal .column {\n    width: 48%;\n    float: left;\n    left: 0;\n}\n\n.info.fillParent {\n    float: none;\n}\n\n.info.fillParent .footer {\n    bottom: -10px;\n}\n\n.panel.info.nothingToDisplay {\n    border: none;\n    background-color: transparent;\n}\n\n.panel.info.noDataModeDisplay {}\n\n\n/* ----------------------- */\n/*  4. INFO, SYSTEM PANEL  */\n/* ----------------------- */\n.info.system {\n    height: 25px;\n    min-height: 0;\n    min-width: 0;\n    margin: 3px;\n    background-color: #feef97; /* TODO: define new color and variable */\n}\n\n.info.system > .content {\n    /* set coordinates to visual (0,0,0,0) of .column.decorated background,\n       as this object used as reference for positioning\n       child objects */\n    left: -3px;\n    margin-bottom: -1px;\n    margin-right: -5px;\n    position: relative;\n    top: -3px;\n    text-align: center;\n}\n\n.info.system .body {\n    padding: 0;\n}\n\n.info.system .message {\n    font-weight: bold;\n    line-height: 32px;\n    margin: auto 10px;\n    overflow: hidden;\n    white-space: nowrap;\n}\n\n#systemMessageConsole {\n    background-color: #feef97; /* TODO: define new color and variable */\n    height: 40px;\n    position: absolute;\n    top: -1px;\n    right: 0;\n    left: 0;\n    z-index: 9;\n}\n\n#systemMessage {\n    color: var(--theme-medium-dark);\n    font-family: source_sans_prosemibold, Franklin Gothic Medium, Verdana, Arial, sans-serif;\n    font-size: 14px;\n    line-height: 40px;\n    margin: 0;\n    padding: 0;\n    text-align: center;\n}\n\n#systemMessage span {\n    color: #333;\n}\n\n#systemMessage span a {\n    font-family: source_sans_proregular, Franklin Gothic, Verdana, Arial, sans-serif;\n}\n\n#systemMessage .warning {\n    color: #d81e29; /* TODO: define new color and variable */\n}\n\n\n/* ----------------------- */\n/*  5. NOTHING TO DISPLAY  */\n/* ----------------------- */\n.panel.nothingToDisplay > .content {\n    margin: 0 12px;\n}\n\n.panel.nothingToDisplay .message.emphasis {\n    font-weight:bold;\n}\n\n.panel.nothingToDisplay.hidden {\n    display: none !important;\n}\n\n.panel.nothingToDisplay.info > .content > .body > .message {\n    background-color: #fff;\n    border: 1px solid #D3D2D2;\n    margin: 10px 0;\n    padding: 28px 8px;\n    text-align: center;\n} /* only usage left is settings > adhoc cache */\n\n\n/* ------------------------ */\n/*  6. MISC PANEL CONTENT   */\n/* ------------------------ */\n.panel .row.actions {\n    position: absolute;\n    bottom: 5px;\n}\n\n.panel .row.inputs {\n    margin: 15px 20px 50px;\n    position: absolute;\n    top: 0;\n    left: 0;\n    right: 0;\n    bottom: 0;\n}\n\n.panel.filter .select {\n    margin: auto 10px;\n}','css',NULL),(22,'/*\n * Copyright (C) 2005 - 2020 TIBCO Software Inc. All rights reserved.\n * http://www.jaspersoft.com.\n *\n * Unless you have purchased a commercial license agreement from Jaspersoft,\n * the following license terms apply:\n *\n * This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU Affero General Public License as\n * published by the Free Software Foundation, either version 3 of the\n * License, or (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE. See the\n * GNU Affero General Public License for more details.\n *\n * You should have received a copy of the GNU Affero General Public License\n * along with this program. If not, see <http://www.gnu.org/licenses/>.\n */\n\n/*\nnot for production, this file contains styles that are used \nfor the sample pages\n*/\n\n\n#sampleGrid {\n	margin:10px;\n}\n\n#sampleGrid td,\n#sampleGrid th {\n	padding:15px;\n	border:1px solid #e0e0e0;\n	width: 200px;\n}\n\n\n#menus #sampleGrid td.example {\n	width:400px;\n}\n\n\n#sampleGrid th * {\n	width:100%\n}\n\n#sampleGrid #calendarSample td,\n#sampleGrid #calendarSample td{\n	padding: 3px;\n	border: inherit;\n}\n\n.rowHeader {\n	width:100px;\n	text-align: right;\n	background: none;\n}\n\ntr#frame {\n	position: static;\n	background: none;\n}\n\ntd.example {\n	vertical-align: top;\n	position: relative;\n}\n\n.positioningContext {\n	position: relative;\n}\n\n#sampleGrid td.noPadding {\n	padding: 0;\n}\n\n.toolbar td {\n	vertical-align: middle;\n	padding:0;\n}\n\n.footer.container td {\n	background-color: #E6E6E6;\n}\n\n@-moz-document url-prefix() {\n	.toolbar.container td {\n		height:38px;\n	}\n}\n\n#panels .panel {\n	position: relative;\n}\n\n#panels .column.primary .header > .title {\n    padding-left:14px;\n}\n\n#ShipCountryPodfilter_2_filterInputContainer select {\n	width:97%\n}\n\n#panels .pane.filter.sizeable .all {\n    bottom: -2px;\n    position: absolute;\n}\n\n#dialogs #sampleGrid .dialog {\n	position: relative;\n	left:0 !important;\n	top:0 !important;\n	margin-left: 0 !important;\n	margin-top: 0 !important;\n}\n\n#dialogs #sampleGrid .dialog.login {\n	*width:240px; /* IE7 */\n}\n\n#dialogs #sampleGrid .login .header {\n	background:url(images/column_header_bkgd.png) repeat-x #fff;\n	border-bottom: 1px solid #C5C5C5;\n}\n\n#dialogs #sampleGrid #generatorSelect .body {\n	width:400px;-moz-box-sizing: border-box; -webkit-box-sizing: border-box; box-sizing: border-box;\n	\n}\n\n#dialogs #sampleGrid #generatorSelect .list.locations .control.browser {\n	width:95%;\n	\n}\n\n\n/* iPads (portrait and landscape) */\n@media only screen \nand (min-device-width : 768px) \nand (max-device-width : 1024px) {\n	\n	#dialogs #sampleGrid .dialog.overlay.addUser > .content > .footer>.action {\n		top:-34px;\n	}\n}\n\n#lists .list.tabular.resources {\n	margin-top:0;\n}\n\n#lists .list.resources .resourceName {\n	height:20px;\n}\n\n#lists .list.resources .modifiedDate {\n	border-left: none;\n}\n\n#chooseSource {\n	position: relative;\n	top:auto;\n}\n\n#addResource .dialog {\n	position: relative;\n}\n\n.toolbar.container.labelsAndIcons td{\n	height:50px;\n}\n\n#sample {\n	background-image: url(themes/pods/images/sampleIcon_20x20.png);\n}\n\nbutton #inputs {\n	background-image: url(images/icons/button_filter.png);\n}\n\n.toolbarContainer .toolbar {\n	*width:1600px; /* IE7 */\n}\n\n#sampleGrid .menu.vertical {\n	position:relative;\n}\n\n#sampleGrid .sub.menu {\n	position:absolute;\n}\n\n#sampleGrid .toolbar>button {\n	margin-top:2px;\n	margin-left:4px;\n}\n\n.horizontalNav .header {\n	position: relative;\n	height:26px;\n	line-height:26px;\n	background: url(\"images/banner_bkgd.png\") repeat-x scroll 0 0 #2881BB;\n}\n\n.horizontalNav .header *{\n	height:26px;\n	line-height: 26px;	\n}\n\n.menu.horizontal {\n	top:0;\n	left:0;\n}\n\n#panels .pane {\n	margin:0;\n}\n\n.action.jumbo {\n	*width: 247px; /* IE7 */\n}\n\n#login .content>.footer {\n	height:auto;\n}\n\n.example .list.collapsible.folders>.folders>.wrap {\n	line-height:20px\n}\n\n.FPOonly {\n	background: #f6f9f9 url(images/grid_20x20_bkgd.png);\n}\n\n#panels .FPOonly {}\n\n.a {\n	height: 300px;\n	width:100%;\n}\n\n.b {\n	height:400px;\n	width:300px;\n}\n\n.c {\n	height:150px;\n	width:400px;\n}\n\n.d {\n	height:100px;\n	width:200px;\n}\n\n/*  testing again  */','css',NULL),(23,'/*\n * Copyright (C) 2005 - 2020 TIBCO Software Inc. All rights reserved.\n * http://www.jaspersoft.com.\n *\n * Unless you have purchased a commercial license agreement from Jaspersoft,\n * the following license terms apply:\n *\n * This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU Affero General Public License as\n * published by the Free Software Foundation, either version 3 of the\n * License, or (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE. See the\n * GNU Affero General Public License for more details.\n *\n * You should have received a copy of the GNU Affero General Public License\n * along with this program. If not, see <http://www.gnu.org/licenses/>.\n */\n\n.simpleColorPicker{\n    width: 268px;\n    position: absolute;\n    z-index: 9999;\n    background-color: #ffffff;\n    border: 1px solid #CCCCCC;\n    box-shadow: 0 0 4px 4px rgba(51, 51, 51, 0.5);\n}\n\n.simpleColorPicker .body{\n    max-height: 480px;\n    overflow-y: auto;\n    overflow-x: hidden;\n    /* padding: 3px; */\n    margin: 12px;\n    position: relative;\n}\n\n.simpleColorPicker .color{\n    width: 16px;\n    height: 16px;\n    float: left;\n    cursor: pointer;\n}\n\n.simpleColorPicker .body .color.transparent, .simpleColorPicker .body .color.none{\n    border: 1px solid #9e9e9e;\n    width: 234px;\n    height: 20px;\n    line-height: 18px;\n    padding-left: 4px;\n    margin: 4px;\n    background-color: rgba(0, 0, 0, 0);\n    cursor: pointer;\n}\n\n.simpleColorPicker .header{\n    position: relative;\n    background-color: #e3e3e3;\n    color: #195b8a;\n}\n\n.simpleColorPicker .header h2{\n    text-align: left;\n    margin: 0 0 0 10px;\n    cursor: default;\n    padding: 0 4px;\n    font-size: 12px;\n    line-height: 28px;\n}\n\n.simpleColorPicker .footer{\n    position: relative;\n    padding: 8px;\n    height: auto;\n    text-align: left;\n    border-top: solid 1px #d3d5d6;\n    overflow: hidden;\n}\n\n.simpleColorPicker .colorWrapper{\n    width: 16px;\n    height: 16px;\n    float: left;\n    margin: 4px;\n}\n\n.simpleColorPicker .colorWrapper.selected {\n    /* padding: 1px; */\n    /* margin: 0; */\n    /* border: 3px solid orange; */\n    outline: 2px solid orange;\n}\n\n.simpleColorPicker .body .color.transparent.selected, .simpleColorPicker .body .color.none.selected {\n    /* padding: 1px; */\n    /* margin: 1px; */\n    border: 1px solid #fff;\n    outline: 2px solid orange;\n}\n','css',NULL),(24,'/*\n * Copyright (C) 2005 - 2022 TIBCO Software Inc. All rights reserved.\n * http://www.jaspersoft.com.\n *\n * Unless you have purchased a commercial license agreement from Jaspersoft,\n * the following license terms apply:\n *\n * This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU Affero General Public License as\n * published by the Free Software Foundation, either version 3 of the\n * License, or (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE. See the\n * GNU Affero General Public License for more details.\n *\n * You should have received a copy of the GNU Affero General Public License\n * along with this program. If not, see <http://www.gnu.org/licenses/>.\n */\n\n/* --------------------------------------\n   TABLE OF CONTENTS\n\n    1. VARIABLES\n       1a. colors\n\n    2. FONTS\n\n    3. BRANDING LOGO\n\n    4. HTML ELEMENTS\n\n    5. TYPOGRAPHY\n       5a. sizes/styling\n       5b. colors\n\n    6. UTILITY\n\n    7. MISCELLANEOUS\n\n    8. ACCESSIBILITY\n\n    9. JIF SCRIPTING CLASSES\n\n   -----------------------------------\n    File last modified Feb 8, 2023\n   -----------------------------------  */\n\n/* ----------------- */\n/*  1. VARIABLES     */\n/* ----------------- */\n/*  1a. colors       */\n/* ----------------- */\n:root{\n    --theme-light:          #e0f0f9;\n    --theme-medium-light:   #0078bd;\n    --theme-medium-dark:    #01529a;\n    --theme-dark:           #062e79;\n\n    --adhoc-field:          #91d9ed;\n    --adhoc-field-border:   #53b7d3;\n    --adhoc-field-text:     #027392;\n    --adhoc-measure-light:  #dff8b0;\n    --adhoc-measure-dark:   #b6d978;\n    --adhoc-measure-border: #6f9d1e;\n    --adhoc-measure-text:   #527218;\n\n    --adhoc-field-token-text:     #0f4552;\n    --adhoc-measure-token-text:   #314a04;\n\n    --background-white:     #ffffff;\n    --background-grey-02:   #fafafa;\n    --background-grey-03:   #f7f7f7;\n    --background-grey-04:   #f4f4f4;\n    --background-grey-08:   #ebebeb;\n    --background-grey-10:   #e4e4e4;\n    --background-grey-16:   #d6d6d6;\n    --background-grey-20:   #cccccc;\n    --background-grey-29:   #b5b5b5;\n    --background-grey-40:   #999999;\n    --background-grey-47:   #878787; /* added for accessibility contrast story */\n    --background-grey-54:   #757575; /* added for accessibility contrast story */\n\n    --border-white:         #ffffff;\n    --border-grey-06:       #f0f0f0;\n    --border-grey-10:       #e4e4e4;\n    --border-grey-13:       #dedede;\n    --border-grey-16:       #d6d6d6;\n    --border-grey-20:       #cccccc;\n    --border-grey-29:       #b5b5b5;\n    --border-grey-40:       #999999;\n    --border-grey-47:       #878787;\n    --border-grey-60:       #666666;\n\n}\n\n\n\n/* ------------- */\n/*  2. FONTS     */\n/* ------------- */\n/* Formats woff and woff2 generated from Font Squirrel */\n/* Formats ttf are from TIBCO UXPL, renamed to lower-case */\n@font-face {\n    font-family: \'source_sans_proregular\';\n    src: url(\'fonts/sourcesanspro-regular-webfont.woff2\') format(\'woff2\'),\n    url(\'fonts/sourcesanspro-regular-webfont.woff\') format(\'woff\');\n    url(\'fonts/sourcesanspro-regular.ttf\') format(\'ttf\');\n    font-weight: normal;\n    font-style: normal;\n}\n\n@font-face {\n    font-family: \'source_sans_prosemibold\';\n    src: url(\'fonts/sourcesanspro-semibold-webfont.woff2\') format(\'woff2\'),\n    url(\'fonts/sourcesanspro-semibold-webfont.woff\') format(\'woff\');\n    url(\'fonts/sourcesanspro-semibold.ttf\') format(\'ttf\');\n    font-weight: normal;\n    font-style: normal;\n}\n\n@font-face {\n    font-family: \'source_sans_probold\';\n    src: url(\'fonts/sourcesanspro-bold-webfont.woff2\') format(\'woff2\'),\n    url(\'fonts/sourcesanspro-bold-webfont.woff\') format(\'woff\');\n    url(\'fonts/sourcesanspro-bold.ttf\') format(\'ttf\');\n    font-weight: normal;\n    font-style: normal;\n}\n\n\n\n/* ------------------- */\n/*  3. BRANDING LOGO   */\n/* ------------------- */\n#logo {\n    background-image: url(images/logo_reverse.svg);\n    background-repeat: no-repeat;\n    background-color: transparent;\n    background-position: 0 0;\n    background-size: contain;\n    border: none;\n    height: 24px;\n    width: 140px;\n    margin: 8px 4px 0 8px;\n}\n\n\n\n/* ------------------- */\n/*  4. HTML ELEMENTS   */\n/* ------------------- */\nhtml,\nbody {\n    height: 100%;\n	width: 100%;\n}\n\nbody {\n	position: relative;\n}\n\n@media only screen\nand (min-device-width : 768px)\nand (max-device-width : 1024px)\nand (orientation: portrait) {\n	body {\n		min-width:768px;\n	}\n}\n\n\nh1, h2, h3, h4, h5, h6 {\n    clear: both;\n	font-weight: bold;\n}\n\nh1 {\n    font-size: 18px;\n    line-height: 1.818em;\n	margin-bottom: 1.3em;\n}\n\nh2 {\n    font-size: 16px;\n    line-height: 1.636em;\n	margin-bottom: 0.7em;\n}\n\nh3 {\n    font-size: 12px;\n    line-height: 1.272em;\n    margin-bottom: 0.7em;\n}\n\nh4 {\n    margin-bottom: 0.7em;\n}\n\nh5 {\n    font-size: 10px;\n    line-height: 1.091em;\n    margin-bottom: 0.5em;\n}\n\nh6 {\n    font-size: 9px;\n    margin-bottom: 0.5em;\n}\n\np {\n	margin-bottom: 1em;\n}\n\na {\n	color: inherit;\n    cursor: pointer;\n	text-decoration: none;\n}\n\naddress	{\n    font-style: italic;\n	margin: 0 0 1.5em;\n}\n\ndel {\n	color: #666;\n}\n\npre {\n	margin: 1.5em 0;\n	white-space: pre;\n}\n\npre,\ncode,\ntt {\n	font: 1em \'andale mono\', \'lucida console\', monospace;\n	line-height: 1.5;\n}\n\n.dimmer {\n	filter: alpha(opacity=60);\n}\n\n.msshadow {\n	filter:\n		progid:DXImageTransform.Microsoft.Shadow(Strength=4, Direction=0, Color=\'#7d7d7d\'),\n		progid:DXImageTransform.Microsoft.Shadow(Strength=3, Direction=45, Color=\'#7d7d7d\'),\n		progid:DXImageTransform.Microsoft.Shadow(Strength=4, Direction=90, Color=\'#7d7d7d\'),\n		progid:DXImageTransform.Microsoft.Shadow(Strength=3, Direction=135, Color=\'#7d7d7d\'),\n		progid:DXImageTransform.Microsoft.Shadow(Strength=4, Direction=180, Color=\'#7d7d7d\'),\n		progid:DXImageTransform.Microsoft.Shadow(Strength=3, Direction=225, Color=\'#7d7d7d\'),\n		progid:DXImageTransform.Microsoft.Shadow(Strength=4, Direction=270, Color=\'#7d7d7d\'),\n		progid:DXImageTransform.Microsoft.Shadow(Strength=3, Direction=315, Color=\'#7d7d7d\');\n} /* can we delete this? */\n\n/* States */\na:focus,\na:hover,\na:active {\n    text-decoration: underline;\n}\n\na:active {\n    color: var(--theme-dark);\n}\n\na.disabled,\na.disabled:hover,\na.disabled.over,\na.disabled:active,\na.disabled.pressed {\n    cursor: default;\n    text-decoration: none;\n}\n\n.selected a:focus,\n.selected a:hover,\n.selected a.over,\n.selected a:active,\n.selected a.pressed {\n    color: inherit;\n}\n\n/* Keyboard Focus */\n:focus:not(.focus-visible) {\n    outline: none\n}\n\na:focus-visible:not(.button) {\n    background-color: #bde7ff;\n    box-shadow: 0 -2px #bde7ff, 0 2px var(--theme-dark);\n    color: var(--theme-dark) !important;\n    text-decoration: none;\n}\n\n.message.focus-visible {\n    background-color: #bde7ff;\n    color: #212121;\n    outline: 2px solid var(--theme-dark);\n}\n\n\n\n/* -------------------- */\n/*  5. TYPOGRAPHY       */\n/* -------------------- */\n/*  5a. sizes/styling   */\n/* -------------------- */\n body,\n textarea,\n input,\n select,\n.body,\n.title > .path,\n.default,\n.message,\n.message.warning {\n    font-family: Verdana, Arial, Helvetica, sans-serif;\n    font-size: 11px;\n    font-weight: normal;\n    line-height: 1.182em;\n}\n\n.data.table .caption,\n.larger,\n.wrapper.table .caption {\n	font-size: 16px;\n	line-height: 1.636em;\n}\n\n#calculatedField .operator,\n.fsection,\n.large,\n.list.settings .node>.wrap .title,\n.menu,\n.searchLockup > input {\n	font-size: 12px;\n	line-height: 1.272em;\n}\n\n.pane.filter .message,\n.panel.widget .title,\n.small {\n	font-size: 10px;\n	line-height: 1.091em;\n}\n\n.control.path .last,\n.emphasis,\n.list p.ID,\n.overlay .group .header,\n#reportContainer a,\n.title,\n.wrapper.table .caption .placeholder {\n	font-weight: bold;\n}\n\n/* Ensure links in lists receive underlines when the cursor is over them. */\n.list.resources .cursor p.resourceName a {\n    text-decoration: underline;\n}\n\n#reportContainer .inputControls a {\n    font-weight: normal;\n}\n\n/* -------------- */\n/*  5b. colors    */\n/* -------------- */\n/* .white */\n.palette01,\n.selected > .wrap .launcher {\n	color: #fff;\n}\n\n.palette02,\n.node.readonly > .wrap {\n	color: #E0E0E0;\n}\n\n/* .gray20 */\n.palette03,\n.button.action.checking,\n.button.action.checking.over,\n.button.action.checking.pressed,\n.disabled,\n.button.disabled,\n[disabled] {\n	color: #aaa;\n}\n\n/* .gray40 */\n.filters .fieldName,\n.filters .condition,\n.horizontal,\n.palette04,\n.sub.header,\n.tabSet.buttons .disabled .button {\n	color: #999;\n}\n\n/* .gray60 */\nlegend,\nlegend.label > .wrap,\n#addResource_locateDataSource #newDataSourceLink.disabled,\n#addResource_locateQuery #newQueryLink.disabled,\n#addResource_inputControl_information .list.twoColumn > .node > .wrap,\n.attributesDesigner .baseTable,\n.attributesViewer .baseTable,\n.attributesTable > .thead .table-column,\n.attributesTable > .tbody .table-row,\n.foundItem,\n.group legend.label,\n.list.collapsible > li > .header.wrap,\n.list.inputSet,\n.list.settings .node > .wrap .title,\n.list.twoColumn > .node > .wrap,\n.LogCollectors .collectorsList tr td,\n.manager .entities.header > .leaf > .wrap,\n.resourceBlock .fileType,\n#serverError h3 {\n	color: #666;\n}\n\n/* .gray80 */\n.palette06,\nbody,\n*[readonly=readonly],\n.group > legend,\n.menu li,\n.title > .path {\n	color: #333;\n}\n\n.list.settings .node > .wrap .title {\n	color: #444;\n}\n\n/* theme medium-dark blue */\n.palette11,\n.fsection,\n.panel.info.system .message,\n.textAccent02 {\n    color: var(--theme-medium-dark);\n}\n\n#reportContainer .inputControls a {\n    color: inherit;\n}\n\n/* .orange4 */\n.palette16,\n.button.capsule.down.disabled,\n.button.capsule.down[disabled],\n.resourcePath {\n	color: #dc5717;\n}\n\n/* .red */\n.palette17,\n.warning,\n.errorMessage,\n.invalid>.wrap,\n.error>.message.warning a.details:active {\n    color: #d81e29;\n}\n\n/* green */\n.palette18,\n.notification.success>.message.warning,\n.success {\n    color: #7a9f35;\n}\n\n.palette01_bkgd {background-color:#fff;}\n.palette02_bkgd {background-color:#e0e0e0;}\n.palette03_bkgd {background-color:#ccc;}\n.palette04_bkgd {background-color:#999;}\n.palette05_bkgd {background-color:#666;}\n.palette06_bkgd {background-color:#333;}\n.palette07_bkgd {background-color:#000;}\n.palette08_bkgd {background-color:#43B9F9;}\n.palette09_bkgd {background-color:#4698be;}\n.palette10_bkgd {background-color:#8CD9FE;}\n.palette11_bkgd {background-color:#217EB5;}\n.palette12_bkgd {background-color:#0061a2;}\n.palette13_bkgd {background-color:#FC870E;}\n.palette14_bkgd {background-color:#FB5B0D;}\n.palette15_bkgd {background-color:#7A3E10;}\n.palette16_bkgd {background-color:#DC5717;}\n.palette17_bkgd {background-color:#f00;}\n.transparent {background-color: transparent;}\n\n\n\n\n/* --------------- */\n/*  6. UTILITY     */\n/* --------------- */\n.offLeft,\n.offLeft span,\n.wrap.offLeft,\n.wrap.header.offLeft {\n    /* hide, but leave it available to screen reader */\n	position: absolute !important;\n	left: -9999px;\n	width:9999px;\n	z-index: -5;\n}\n\n.centering {\n    /* only centers if object has explicit width */\n	margin: 0 auto;\n	position: relative;\n}\n\n* {\n    box-sizing: border-box;\n}\n\n\n\n/* -------------------- */\n/*  7. MISCELLANEOUS    */\n/* -------------------- */\n#systemConfirm {\n	position: absolute;\n	top: 10px;\n    right: 220px;\n	left: 500px;\n	z-index: 5;\n}\n\n.dimmer {\n	position: absolute;\n	top: 0;\n    right: 0;\n    bottom: 0;\n	left: 0;\n	background-color: #000;\n	opacity: .6;\n}\n\n.dimmer.fixed {\n	position: fixed;\n	z-index: 4999;\n}\n\n#userCountExceeded {\n	position: absolute;\n	top: 14px;\n	left: 470px;\n}\n\ninput[type=text]::-ms-clear {\n    display: none;\n}\ninput[type=password]::-ms-reveal {\n    display: none;\n}\n\n.clear {\n    clear: both;\n    height: 1px!important;\n    line-height: 1px!important;\n    overflow: hidden!important;\n}\n\n\n\n/* -------------------- */\n/*  8. ACCESSIBILITY    */\n/* -------------------- */\n/* Standard Navigation classes and styles\n *\n * The Standard Navigation accessibility system (StdNav) provides some special\n * CSS class to augment the normal \":focus\" pseudoclass available to track\n * browser focus.  By default, only the familiar dashed-line \":focus\" indicator\n * is used.  This focus indication is as per W3C recommendations, and is\n * generally expected by users.\n *\n * However, additional classes are available as well, and are described below.\n * If you wish to use these, you should start by using and modifying the \"Easy\n * Access\" theme, or a copy of it.\n *\n * ==========================================================================\n * superfocus   A class given to exactly one element in the page at all times\n *              to indicate which major UI region is the user\'s current \"area\n *              of interest\".  This will generally either be, or contain, the\n *              browser focus, but will generally be broader than browser\n *              focus.  Jaspersoft extension.\n *\n * :focus       The normal browser focus metaclass.  However, for reasons of\n *              accessibility and navigation, be aware that focus can and will\n *              be set on items that TEMPORARILY have a valid tabindex, but\n *              will not necessarily retain it after navigation (such as an\n *              individual table cell).  Note that when a user is using pure\n *              keyboard navigation, there will be times when NO element in the\n *              page has :focus because the user is tabbing through browser\n *              toolbars, etc.  For screen readers, this is the element whose\n *              content we want to be read, and whose navigation details we\n *              expect to be relayed.\n *\n * subfocus     Fine navigation focus.  Normally, this is applied to the same\n *              element as :focus, but if it is necessary to indicate position\n *              within the child subdom of an element without moving browser\n *              focus to those elements, subfocus may be changed instead.  In\n *              any case, subfocus must always be set correctly, even if it\n *              is simply to the same element that has :focus.  Jaspersoft\n *              extension.\n *\n * ghostfocus - Whenever a major UI region has superfocus, either it or a child\n *              element must have browser TAB focus and StdNav subfocus.  When\n *              superfocus moves to another major UI region-- for example, when\n *              the user presses TAB-- subfocus is replaced by ghostfocus in\n *              the de-focused region.  Likewise, if an element in the newly\n *              superfocused region has ghostfocus, that is replaced by\n *              subfocus.  Finally, the browser is explicitly focused to the\n *              new subfocus (the old ghostfocus, if there was one, or a\n *              sensible default for the region).  This functionality allows a\n *              user to tab back and force between grids, tables, lists, and\n *              other complex controls without losing their place.  Jaspersoft\n *              extension, and not in use by all control types.\n */\n.superfocus {}\n:focus {}\n.subfocus {}\n\n/* button focus */\n.button.action.pressed.subfocus {\n	outline: none;\n}\n\n.resourceBlock .fileName.subfocus a {\n	 text-decoration: underline;\n }\n\n.resourceBlock li.subfocus a {\n	text-decoration: underline;\n}\n\n.workflow-description a.superfocus.subfocus {\n	color: #195b8a;\n}\n\n.workflow-buttonContainer .button.superfocus.subfocus {\n	text-decoration: underline;\n}\n\n#rotating li[role=\"link\"]:focus {\n	text-decoration: underline;\n}\n\n/* control focus */\n@media screen and (-webkit-min-device-pixel-ratio:0)\n{\n	select:focus {\n        outline: 2px solid #062e79;\n	}\n}\n\n\n\n/* --------------------------- */\n/*  9. JIF SCRIPTING CLASSES   */\n/* --------------------------- */\n/*\nScripting classes represent a kind of API for the JIF interactive and layout logic.\n\nSome of the selectors in this group are used as flags for the framework interactive logic to embue\nobjects with specific behavior or layout.\n\nOthers are the selectors that are assigned to objects automatically.\n*/\n\n.centered_horz {\n    /* note: any object assigned this class will\n    automatically be assigned margin-left: -(this.width/2)\n    */\n    position: absolute;\n}\n\n.centered_vert {\n    /* note: any object assigned this class will\n    automatically be assigned margin-top: -(this.height/2)\n    */\n    position: absolute;\n}\n\n.sizer {\n    /* an object with this class can be dragged to size\n       its parent only if the parent has class .sizeable\n    */\n}\n\n.sizeable {\n    /* an object with this class can be resized only\n       if it contains a child with class .sizer\n    */\n}\n\n.mover {\n    /* an object with this class can be dragged to move\n       its parent only if the parent has class .moveable\n    */\n    cursor: move;\n}\n\n.moveable {\n    /* an object with this class can be dragged only if it has a\n       child with class .moveable upon which a mouseMove event occurs\n    */\n}\n\n.draggable {\n    /* an object with this class can be dragged directly\n    */\n}\n\n.wrap.dragging,\n.overlay.col.dragging,\n.overlay.group.dragging,\n.overlay.xtab.gr.dragging,\n.overlay.xtab.m.dragging,\n.overlay.legend.dragging,\n.dragMultiple.dragging .wrap {\n    /* an object being dragged gets the .dragging class applied */\n    background-color: #0081cb !important;\n    border: none !important;\n    border-radius: 3px;\n    color: #fff !important;\n    cursor: hand !important;\n    float: left;\n    font-family: source_sans_proregular, Franklin Gothic, Verdana, Arial, sans-serif;\n    font-size: 12px;\n    height: 22px;\n    line-height: 22px;\n    margin: 3px 2% 0 2px;\n    opacity: .8 !important;\n    padding: 0 8px;\n    width: auto !important;\n}\n\n.copy {\n    cursor:url(\"images/cursor_copy.cur\"), default !important;\n}\n\n.copy .dropTarget {\n    cursor:url(\"images/cursor_copy.cur\"), default !important;\n}\n\n.dropTarget {\n    /* an object that is a valid drop target during a drag gets\n       this class applied when the dragged object is on top of it\n    */\n    background-color: #A9CADD !important;\n}\n\n.button {\n    /* an object with this class will have its class attribute modified by mouse events:\n        - onMouseOver, .over added\n        - onMouseDown, .over removed, .pressed added\n        - onMouseOut, .over || .pressed removed\n       in addition, onMouseUp will trigger a generic event for the object caught by the buttonHandler\n    */\n}\n\n.over {\n    /* added to the class attribute of element.button onMouseOver\n    */\n}\n\n.pressed {\n    /* added to the class attribute of element.button onMouseDown\n    */\n}\n\n.noBubble {\n    /* an object with this class will get mouse events,\n       but will not permit those eventsto bubble up the DOM\n    */\n}\n\n.button.toggle {\n    /* this element will always have either class attribute .up or .down\n       value switched onMouseUp\n    */\n}\n\n.up {\n    /* assigned automatically to .button.toggle\n    */\n}\n\n.down {\n    /* assigned automatically to .button.toggle\n    */\n}\n\n.button.minimize {\n    /* a special button understood to toggle the visible state of its\n       parent container from a regular size to a .minimized state\n    */\n}\n\n.minimized {\n    /* assigned or removed from a container by a mouseUp\n       on the container\'s .button.minimize child\n    */\n}\n\n.node {\n    /* a list element understood to be a parent of another list; always\n       has either .open or .closed as part of its class attribute\n    */\n}\n\n.open {\n    /* assigned automatically to li.node\n    */\n}\n\n.closed {\n    /* assigned automatically to li.node\n    */\n}\n\n.leaf {\n    /* a list element that does not contain another list\n    */\n}\n\n.selected {\n    /* assigned to the currently selected list element\n    */\n}\n\n.editMode {\n    /* assigned automatically to forms based on a user event, this flag is then\n       used to conditionally hide or show form objects as appropriate\n    */\n}\n\n.hidden {\n    /* rather than set the display value inline, scripts use this\n       selector to hide or show objects based on user events\n    */\n    display: none !important;\n}\n\n.resizeOverlay {\n    /* covers resizable panel during resizing to prevent panel\'s elements events */\n    position: absolute;\n    top: 0;\n    right: 0;\n    bottom: 0;\n    left: 0;\n}','css',NULL),(25,'/*\n * Copyright (C) 2005 - 2021 TIBCO Software Inc. All rights reserved.\n * http://www.jaspersoft.com.\n *\n * Unless you have purchased a commercial license agreement from Jaspersoft,\n * the following license terms apply:\n *\n * This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU Affero General Public License as\n * published by the Free Software Foundation, either version 3 of the\n * License, or (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE. See the\n * GNU Affero General Public License for more details.\n *\n * You should have received a copy of the GNU Affero General Public License\n * along with this program. If not, see <http://www.gnu.org/licenses/>.\n */\n\n@import url(\"theme.css\") screen,print;\n@import url(\"pages.css\") screen,print;\n@import url(\"containers.css\") screen,print;\n@import url(\"dialog.css\") screen,print;\n@import url(\"buttons.css\") screen,print;\n@import url(\"lists.css\") screen,print;\n@import url(\"controls.css\") screen,print;\n@import url(\"dataDisplays.css\") screen,print;\n@import url(\"pageSpecific.css\") screen,print;\n@import url(\"dialogSpecific.css\") screen,print;\n\n@import url(\"forPrint.css\") print;\n','css',NULL),(26,'/*\n * Copyright (C) 2005 - 2020 TIBCO Software Inc. All rights reserved.\n * http://www.jaspersoft.com.\n *\n * Unless you have purchased a commercial license agreement from Jaspersoft,\n * the following license terms apply:\n *\n * This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU Affero General Public License as\n * published by the Free Software Foundation, either version 3 of the\n * License, or (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE. See the\n * GNU Affero General Public License for more details.\n *\n * You should have received a copy of the GNU Affero General Public License\n * along with this program. If not, see <http://www.gnu.org/licenses/>.\n */\n\n.webPageView {\n    display: block;\n    height: 100%;\n    width: 100%;\n    overflow: hidden;\n    background-color: #FFFFFF;\n}\n\n.webPageView.loading {\n    background-image: url(\"images/wait_animation_large.gif\");\n    background-position: center center;\n    background-repeat: no-repeat;\n    background-color: transparent;\n}\n\n.webPageView > .externalUrlIframe {\n    border: none;\n    height: 100%;\n    margin: 0;\n    width: 100%;\n    position: relative;\n}\n\n.webPageView > .externalUrlLoadError {\n    color: red;\n    font-weight: bold;\n    text-align: center;\n    margin: 0 auto;\n    padding: 20px;\n    position: relative;\n    top:0;\n    bottom:0;\n    left:0;\n    right:0;\n}\n\n.webPageView.hideLoadingAnimation {\n    background-image: none !important;\n}\n\n.webPageView.invisible {\n    display: none !important;\n    width: 0 !important;\n    height: 0 !important;\n}\n\n.webPageView.touchScroll {\n    display: inline-block;\n    -webkit-overflow-scrolling: touch;\n    overflow-y: scroll;\n}\n.webPageView.touchScroll iframe {\n    display: block;\n}','css',NULL),(27,'/*\n * Copyright (C) 2005 - 2020 TIBCO Software Inc. All rights reserved.\n * http://www.jaspersoft.com.\n *\n * Unless you have purchased a commercial license agreement from Jaspersoft,\n * the following license terms apply:\n *\n * This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU Affero General Public License as\n * published by the Free Software Foundation, either version 3 of the\n * License, or (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE. See the\n * GNU Affero General Public License for more details.\n *\n * You should have received a copy of the GNU Affero General Public License\n * along with this program. If not, see <http://www.gnu.org/licenses/>.\n */\n\n/*\n.overrides_custom css\n\n(Accessible Version)\n\nPlace styles for simple UI customization in this file.\n\nThis file is loaded after all other CSS, so selectors here will win in case of\nconflicts with the default rules.\n\nUsing this file for customizations is the method most likely to conserve your\ncustomizations even if markup changes occur in future product releases.\n\nExtensive customizations may be easier to implement by replacing one or more of\nthe standard theme files in your custom theme folder.  However, if future\nproduct releases place styles for new markup components into the files you have\nreplaced, your theme will not have these new styles, and therefore will not\ndisplay the new components correctly.\n*/\n\n/* Standard Navigation toggle\n * The JavaScript logic that enabled accessible navigation of JRS is enabled by\n * detecting the existance of the class \".js-accessibility-enabled\".  The class\n * defines a single rule to avoid being dropped or optimized out, but is not\n * applied to any element in the DOM.\n *\n * To disable the system, and test visual effects only, comment out this\n * definition.\n */\n.js-accessibility-enabled{\n    border-radius:0;\n}\n\n\n/* Standard Navigation classes and styles\n *\n * The Standard Navigation accessibility system (StdNav) provides some special\n * CSS class to augment the normal \":focus\" pseudoclass available to track\n * browser focus.  By default, only the familiar dashed-line \":focus\" indicator\n * is used.  This focus indication is as per W3C recommendations, and is\n * generally expected by users.\n *\n * However, additional classes are available as well, and are described below.\n * If you wish to use these, you should start by using and modifying the \"Easy\n * Access\" theme, or a copy of it.\n *\n * ==========================================================================\n * superfocus   A class given to exactly one element in the page at all times\n *              to indicate which major UI region is the user\'s current \"area\n *              of interest\".  This will generally either be, or contain, the\n *              browser focus, but will generally be broader than browser\n *              focus.  Jaspersoft extension.\n *\n * :focus       The normal browser focus metaclass.  However, for reasons of\n *              accessibility and navigation, be aware that focus can and will\n *              be set on items that TEMPORARILY have a valid tabindex, but\n *              will not necessarily retain it after navigation (such as an\n *              individual table cell).  Note that when a user is using pure\n *              keyboard navigation, there will be times when NO element in the\n *              page has :focus because the user is tabbing through browser\n *              toolbars, etc.  For screen readers, this is the element whose\n *              content we want to be read, and whose navigation details we\n *              expect to be relayed.\n *\n * subfocus     Fine navigation focus.  Normally, this is applied to the same\n *              element as :focus, but if it is necessary to indicate position\n *              within the child subdom of an element without moving browser\n *              focus to those elements, subfocus may be changed instead.  In\n *              any case, subfocus must always be set correctly, even if it\n *              is simply to the same element that has :focus.  Jaspersoft\n *              extension.\n *\n * ghostfocus - Whenever a major UI region has superfocus, either it or a child\n *              element must have browser TAB focus and StdNav subfocus.  When\n *              superfocus moves to another major UI region-- for example, when\n *              the user presses TAB-- subfocus is replaced by ghostfocus in\n *              the de-focused region.  Likewise, if an element in the newly\n *              superfocused region has ghostfocus, that is replaced by\n *              subfocus.  Finally, the browser is explicitly focused to the\n *              new subfocus (the old ghostfocus, if there was one, or a\n *              sensible default for the region).  This functionality allows a\n *              user to tab back and force between grids, tables, lists, and\n *              other complex controls without losing their place.  Jaspersoft\n *              extension, and not in use by all control types.\n */\n\n/* THEME */\n\n:focus {\n    outline: 1px dotted royalblue;\n}\n\n.superfocus {\n    outline: 3px solid orange;\n}\n\n/* NOTE: Form controls and CSS are not always the best of friends.  Applying\n * global styles can cause problems when the rules fall through to form\n * controls, because even a simple background color change can cause browsers\n * to drop ALL of the default styling for the control, radically changing its\n * appearance.  In particular, Firefox has serious issues with this with respect\n * to \"select\" (dropdown/droplist) controls.\n *\n * This can be gotten around using the :not CSS selector, HOWEVER, be aware that\n * IE8 does not support \":not\".  Conveniently, though, it also doesn\'t have such\n * big issues with CSS styles messing up form controls.\n */\n.subfocus:not(select) {\n    background-color: #c9ebf8;\n}\n\n.ghostfocus {\n}\n\n/* BUTTONS */\n.sourceDialogNew.overlay > .content > .header > .sub.header > .button.superfocus {\n    border: 2px dotted royalblue;\n    outline: none;\n    top: 14px;\n}\n\n.button.action.subfocus {\n    outline: 2px dotted orange;\n}\n\n/* CONTAINERS */\n\n/* CONTROLS */\ninput[type=\"text\"]:focus,\ninput[type=\"password\"]:focus,\nbutton.action:focus,\n#loginPage #metaLinks:focus {\n    outline: 2px dotted orange;\n}\n\n#searchInput:focus {\n    outline: 2px dotted orange;\n}\n\nselect:focus {\n    outline: 2px dotted orange;\n    outline-offset: 1px;\n}\n\n@media screen and (-webkit-min-device-pixel-ratio:0)\n{\n    select:focus {\n        outline: 2px dotted orange;\n        outline-offset: 1px;\n    }\n\n    #searchInput.subfocus {\n        outline-offset: 2px;\n    }\n\n    #secondarySearchInput.subfocus {\n        outline-offset: 0;\n    }\n\n\n    #searchInput.superfocus,\n    #secondarySearchInput.superfocus {\n        outline-offset: 0;\n    }\n}\n\n\n/* TREE */\n.folders.node.selected:focus {\n    outline: 1px dashed royalblue;\n}\n\n/* LISTS */\n.collapsible .list {\n    padding-bottom: 1px; /* prevents clipping of blue dashed focus border on last item in a list */\n}\n\n#logSettings .list.threeColumn .wrap .column.three {\n    height: 28px;\n    padding-left: 4px;\n}\n\n\n#resultsContainer .list .selected.leaf p,\n#resultsContainer .list .selected.node p {\n    color: white;\n}\n\n.subfocus .fileType {\n    color: #333;\n}\n\n.list li.resources.leaf.cursor:focus > div {\n  outline: 3px dotted orange;\n  outline-offset: -3px;\n}\n\n.list li.resources.leaf.cursor:not(.selected) > div {\n    background-color: #CCC;\n}\n\n/* GLOBAL BANNER AND NON-MENU CONTENTS */\n.banner {}\n\n#systemMessageConsole {\n    border-bottom: 1px solid #1388d8;\n    height: 29px;\n}\n\n#systemMessage {\n    line-height: 28px;\n}\n\n/* MENUS */\n#mainNavigation {\n    top: 3px;\n}\n\n#mainNavigation.menu .node,\n#mainNavigation.menu .leaf {\n    /* needed for white dotted focus outline to appear correctly */\n    position: static;\n}\n\n.menu.primaryNav #main_home .wrap > .icon {\n    background-position: 0 0;\n    height: 26px;\n}\n\n#mainNavigation.horizontal li:focus {\n    outline-style:dotted;\n    outline-width:2px;\n    outline-color:white;\n}\n\n#mainNavigation.horizontal li.subfocus {\n    background-color: #157bc1;\n}\n\n.menu.primaryNav .wrap {\n    height: 33px;\n    line-height: 33px;\n}\n\n#metaLinks {\n    height: 33px;\n    line-height: 33px;\n    margin-top: 3px;\n}\n\n#metaLinks li {\n    border: none;\n    line-height: 33px;\n}\n\n\n/* PAGE-SPECIFIC */\n#sortDialogSortFields.superfocus,\n#sortDialogSortFields:focus {\n     outline-offset: -4px;\n}\n\n.sourceDialogNew.superfocus.subfocus {\n    outline: none;\n}\n\n.workflow-iconContainer .button.subfocus:not(select) {\n    background-color: transparent;\n}\n\n\n/* JIVE */\n\n\n/*\n.list .selected .sublist a,\n.list .selected .sublist p a\n{\n    color: #1958ba;\n}\n*/\n\n/*\ntextarea.subfocus {\n    background-color: white;\n}\n*/\n\n#loginPage #loginForm.superfocus,\n#loginPage #metaLinks.superfocus {\n    outline: none;\n}\n\n#loginPage #metaLinks li.subfocus:not(select) a {\n    color: #fff;\n}\n\n#loginPage #metaLinks li.subfocus:not(select) {\n    background-color: #195b8a;\n}\n\n\n/*\n * organization tree\n */\n#orgTree, #orgTree :focus, #orgTree .subfocus li {\n    background-color: transparent;\n}\n\n.workflow.subfocus {\n    background-color: #c9ebf8;\n}\n\n.resourceBlock-table td.subfocus {\n    background-color: #c9ebf8;\n}\n\n.resourceBlock-table td.fileType.subfocus{\n    color: #333;\n}\n\n\n#about > .subfocus:not(select) {\n    background-color: transparent; /* MODIFIED FROM #c9ebf8 */\n    outline: 2px dotted orange;\n}\n\n/*\n * report TOC tabs\n */\n#reportPartsContainer {\n    height: 34px;\n}\n\n#reportPartsContainer.superfocus {\n    margin-top: 3px;\n}\n\n#reportPartsContainer .leaf.subfocus:focus {\n    outline: none;\n}\n\n#reportPartsContainer .leaf.subfocus:not(select) {\n    background-color: transparent;\n}\n\n#reportPartsContainer .leaf.subfocus:focus .button {\n    border: 1px dotted royalblue;\n    border-bottom: none;\n}\n\n#reportPartsContainer .leaf.subfocus:focus .button.active {\n    outline: 1px dotted royalblue;\n    border-color: transparent;\n}\n\n#reportPartsContainer .leaf.control.subfocus:focus .button {\n    outline: 1px dotted royalblue;\n    border: none;\n}\n\n#reportPartsContainer.superfocus .reportPart {\n    height: 31px;\n    top: 3px;\n}\n\n#reportPartsContainer.superfocus .control.search .button {\n    top: -4px;\n}\n\n#reportPartsContainer.superfocus .control.search .button.action.searchPrevious .icon {\n    background-position: 0 3px;\n}\n\n#reportPartsContainer.superfocus .control.search .button.action.searchNext .icon {\n    background-position: 2px -27px;\n}\n\n\n#reportPartsContainer.superfocus .control.search.subfocus .button.action.searchPrevious.over .icon,\n#reportPartsContainer.superfocus .control.search .button.action.searchPrevious.over .icon {\n    background-position: -30px 3px;\n}\n\n#reportPartsContainer.superfocus .control.search.subfocus .button.action.searchNext.over .icon,\n#reportPartsContainer.superfocus .control.search .button.action.searchNext.over .icon {\n    background-position: -28px -27px;\n}\n\n\n#reportPartsContainer.superfocus .control.search .button.action.searchPrevious.over:disabled .icon {\n    background-position: -30px 3px;\n    opacity: 0.5;\n}\n#reportPartsContainer.superfocus .control.search .button.action.searchNext.over:disabled .icon {\n    background-position: -28px -27px;\n    opacity: 0.5;\n}\n\n#reportPartsContainer.superfocus .control.search .button .wrap {\n    margin-top: -2px;\n}\n\n\n/*\n * report toolbar navigation\n */\n#reportViewer .toolbar {\n    height: 33px;\n    border-top: 2px solid #fff;\n}\n\n#reportViewer .toolbar > .buttonSet {\n    margin-left: 3px;\n}\n\n#reportViewer .toolbar > .buttonSet .leaf.subfocus:not(select),\n#reportViewer .toolbar > .toolsRight .leaf.subfocus:not(select) {\n    background-color: transparent;\n}\n\n#reportViewer .toolbar > .buttonSet .leaf:focus,\n#reportViewer .toolbar > .toolsRight .leaf:focus {\n    outline: none;\n}\n\n#reportViewer .toolbar > .buttonSet .leaf:focus .button,\n#reportViewer .toolbar > .toolsRight .leaf:focus .button.action {\n    outline: 1px dotted royalblue;\n}\n\n#reportViewer .control.zoom.subfocus .input:not(select),\n#reportViewer .control.search.subfocus .input:not(select) {\n    background-color: transparent;\n    outline: 2px dotted orange;\n}\n\n#reportViewer .control.paging.subfocus input:not(select) {\n    outline: 2px dotted orange;\n}\n\n#reportViewFrame .header > .list.buttonSet > .leaf.subfocus:not(select) {\n    background-color: transparent;\n}\n\n#viewerToolbar > .toolsRight .control.input > input.subfocus:not(select) {\n    background-color: #fff;\n}\n\n/*\n * report toolbar body\n */\n#reportViewFrame.column.decorated > .content > .body {\n    top: 36px;\n}','css',NULL),(28,'/*\n * Copyright (C) 2005 - 2020 TIBCO Software Inc. All rights reserved.\n * http://www.jaspersoft.com.\n *\n * Unless you have purchased a commercial license agreement from Jaspersoft,\n * the following license terms apply:\n *\n * This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU Affero General Public License as\n * published by the Free Software Foundation, either version 3 of the\n * License, or (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE. See the\n * GNU Affero General Public License for more details.\n *\n * You should have received a copy of the GNU Affero General Public License\n * along with this program. If not, see <http://www.gnu.org/licenses/>.\n */\n\n/*\n.overrides_custom css\n\nPlace styles for simple UI customization in this file.\nThis file is loaded after all other CSS, so selectors here will win in case of conflict with default rules.\nUsing this file to customize is the method most likely to conserve your customizations even if markup changes in future product releases.\nExtensive customizations may be easier to implement by replacing one or more of the standard theme files in your custom theme folder.\nHowever, if future product releases place styles for new markup components into the files you have replaced, your theme will not have these new styles,\nand therefore, will not display the new components correctly.\n\n*/\n\n/* VARIABLES */\n/* cannot use until we drop IE11 support */\n:root {\n    --dark-blue:      #10203f; /* TIBCO midnight */\n    --medium-blue:    #576379  /* TIBCO midnight 30% lighter */\n}\n\n/* BUTTONS */\n.button.capsule.superfocus.subfocus:hover,\n.button.capsule.up.over,\n.button.capsule.down,\n.button.capsule.down.over,\n.button.capsule.down.pressed {\n    background-color: #576379; /* midnight 30% lighter */\n}\n\n.button.capsule.up.pressed,\n.button.capsule.down.over,\n.button.capsule.superfocus.subfocus.pressed {\n    background-color: #10203f; /* midnight */\n}\n\n.action.jumbo.up.pressed {\n    background: none repeat scroll 0 0 #FFFFFF;\n    border: 1px solid #bf5b08;\n}\n\n.action.primary,\n.action.primary.pressed,\n.action.primary.pressed.over {\n    background-image: none;\n    background-color: #10203f; /* midnight */\n}\n\n.action.primary.over {\n    background-color: #576379;\n}\n\n.action.small.up.over,\n.action.small.up.pressed {\n    background-color: #576379; /* midnight 30% lighter */\n}\n\n.action.small.pressed.over,\n.action.small.down,\n.action.small.down.over,\n.action.small.down.pressed,\n.sourceDialogNew .header .button.over.subfocus {\n    background-color: #10203f; /* midnight */\n}\n\n#reportViewer .toolsRight .button.action.up.over,\n#reportViewer .toolsRight .button.action.up.pressed,\n#reportViewer .toolsRight .button.action.down,\n#reportViewer .toolsRight .button.action.down.over,\n#reportViewer .toolsRight .button.action.down.pressed {\n    background-color: #576379; /* midnight 30% lighter */\n}\n\n#designer .toolbar .buttonSet .node > .button.pressed {\n    background-color: #576379; /* midnight 30% lighter */\n}\n\n#tableOptions.over , #chartOptions.over {\n    background-color: #576379; /* midnight 30% lighter */\n}\n\n#reportViewer #asyncCancel,\n#reportViewer .toolbar #fileOptions.pressed,\n#reportViewer .toolbar #export.pressed {\n    background-color: #576379; /* midnight 30% lighter */\n}\n\n#reportPartsContainer .reportPart.active {\n    background-color: #10203f;\n}\n\n#reportPartsContainer .button.action.up.over {\n    background-color: #576379;\n}\n\n#reportPartsContainer .reportPart.over span {\n    color: #083970;\n}\n\n.dashboardToolbar #save.pressed,\n.dashboardToolbar #export.pressed,\n.dashboardCanvas .dashletToolbar .button.text.cancelDashletButton,\n.dashboardCanvas .dashletToolbar .button.exportDashletButton.pressed {\n    background-color: #576379; /* midnight 30% lighter */\n}\n\n.addNewItem, a.addNewItem {\n    border: 1px solid #10203f; /* midnight */\n    color: #10203f; /* midnight */\n}\n\n/* CONTAINERS */\n\n.banner,\n#frameFooter {\n	background-color: #10203f; /* midnight */\n}\n\n.menu.primaryNav .wrap.over,\n.menu.primaryNav .wrap.pressed {\n    background-color: #576379; /* midnight 30% lighter */\n}\n\n#metaLinks li.subfocus:not(select) {\n    background-color: #576379;\n}\n\ncolumn.decorated {\n	border:1px solid #000b2c;\n}\n\n.column.decorated > .content > .header,\n.column.decorated > .content > .header > .subheader {\n    background-color: #f0f2f3;\n}\n\n.panel.tooltip .message.label {\n    color: #10203f; /* midnight */\n}\n\n.menu.vertical li > .wrap.over,\n.menu.vertical li > .wrap.pressed {\n    background-color: #576379 /* midnight 30% lighter */\n}\n\n#systemMessage {\n    color: #035b85;\n    font-weight: bold;\n    text-align: center;\n}\n\n\n/* CONTROLS */\n\n\n/* LISTS */\n/* SELECT LIST CONTROLS */\n\n.list > li > .wrap.pressed,\n.list > li.selected > .wrap,\n.list > li.selected > .wrap.over,\n.sList li.selected,\n.mSelect-svList > .selected .mSelect-svList-button,\n.list.filters > li > .wrap.over,\n.list.filters > li > .wrap.pressed,\n.list.filters > li:not(.selected) > .wrap.over,\n.list.filters > li:not(.selected) > .wrap.pressed {\n	background-color: #576379;\n}\n\n.list.filters > li:not(.selected) > .wrap.over .launcher,\n.list.filters > li:not(.selected) > .wrap.pressed .launcher {\n    color: #fff;\n}\n\n.sList li.active.selected,\n.mSelect-svList > .active.selected .mSelect-svList-button {\n	background-color:#054e71;\n}\n\n.list.tabular.resources.header,\n.list.tabular.jobs.header {\n    background-color: #ecf1f4;\n}\n\n.list.resources.sublist .resourceName > a {\n    color: #083970;\n}\n\n.tabSet.vertical.buttons .button {\n    background-color: #576379;\n}\n\n.tabSet.vertical.buttons .selected .button,\n.tabSet.vertical.buttons .selected .button.over,\n.tabSet.vertical.buttons .selected .button.pressed,\n.tabSet.vertical.buttons .button.pressed,\n.tabSet.vertical.buttons .button.over {\n    background-color: #10203f;\n}\n\n\n/* THEME */\n\n/* sky */\n.palette09,\n.button.action.jumbo,\n.homeSidebar-title,\n.workflow-title,\n.resourceBlock a:link,\n.resourceBlock a:visited,\n.resourceBlock a:hover,\n.resourceBlock a:active,\n.workflow-description a:hover {\n	color:#035b85;\n}\n\n.button.action.primary.disabled,\n.button.action.primary[disabled] {\n    color: #475a72;\n}\n\n.tabSet.buttons.vertical [disabled] {\n    /* eqivalent to .35 opacity */\n    color: #9399a8;\n}\n\n.palette10,\n#metaLinks a:active {\n	color:#92c6de;\n}\n\n/* dark blue in gradient */\n.palette11,\n.column.decorated.minimized .vtitle,\n.tabSet.horizontal.buttons .selected > .button > .wrap,\n#filter-container .filterName,\n#expression-container .filterName,\n#scheduler_editor #stepDisplay > fieldset > legend,\n.textAccent02,\n.tabSet.text .selected.tab>.wrap,\n.tabSet.text .selected.tab>.wrap.over,\n.tabSet.text .selected.tab>.wrap.pressed,\n.list.filters>li.selected>.wrap,\n.list.stepIndicator .selected>.wrap,\n.panel.info.system .message,\n.resourceName,\n.fsection,\n#reportContainer a,\n.plusminus .node>.wrap>.jrbookmark,\n.filterManagerDialog .addNewFilter {\n	color:#035b85;\n}\n\n.palette11,\n.textAccent02,\n.tabSet.text .selected.tab > .wrap,\n.tabSet.text .selected.tab > .wrap.over,\n.tabSet.text .selected.tab > .wrap.pressed,\n.list.filters > li.selected>.wrap,\n.list.filters > li.selected>.wrap.pressed,\n.list.filters > li.selected>.wrap .launcher,\n.list.stepIndicator .selected>.wrap,\n.panel.info.system .message,\n.list.type_basic .wrap a,\n.resourceName,\n.fsection,\n.launcher,\n#reportContainer a,\n#scheduler_editor #stepDisplay > fieldset > legend,\n.homeSidebar-title,\n.workflow-title,\n#resultsContainer .resourceName,\n.resourceBlock a:link,\n.resourceBlock a:visited,\n.resourceBlock a:hover,\n.resourceBlock a:active,\n.workflow-description a:hover,\n.workflow-buttonContainer .button,\n.plusminus .node > .wrap > .jrbookmark,\n.list.settings .panel.pane.settings .header > .title,\n.tabSet.horizontal.buttons .selected > .button > .wrap,\n.tabSet.horizontal.buttons .button.over,\n.tabSet.horizontal.buttons .button.pressed,\n.content .header > .title,\n.resourceBlock-title,\n.column.decorated.minimized .vtitle,\n.flow #stepDisplay .column.primary .header .title,\n.flow #stepDisplay .column.secondary .header .title,\n#loginPage #metaLinks li,\n#loginPage #metaLinks a,\n#loginPage #metaLinks a:hover,\n#loginPage #metaLinks a:active,\n#needHelp {\n    color: #083970;\n}\n\n/* orange */\n.palette13,\n.textAccent,\n.button.action.jumbo.over {\n	color:#dd770d;\n}\n\n/* .orange2 */\n.palette14,\n#needHelp:active,\n.button.action.jumbo.pressed {\n	color:#bf5b08;\n}\n\n/* orange3 */\n.palette15,\n.button.capsule.down {\n	color: #532a0a;\n}\n\n/* orange4 */\n.palette16,\n.button.capsule.down.disabled,\n.button.capsule.down[disabled],\n.resourcePath {\n	color: #9f481d;\n}\n\n.wrap.dragging,\n.overlay.col.dragging,\n.overlay.group.dragging,\n.overlay.xtab.gr.dragging,\n.overlay.xtab.m.dragging,\n.overlay.legend.dragging,\n.dragMultiple.dragging .wrap {\n	/* an object being dragged gets the .dragging class applied */\n	background-color:#035b85 !important;\n}\n\n#frameFooter #about a,\n#frameFo