anvas.jr, caption.jr, div.jr, em.jr, embed.jr,\nfieldset.jr, form.jr, h1.jr, h2.jr, h3.jr, h4.jr,\nh5.jr, h6.jr, i.jr, iframe.jr, img.jr, label.jr,\nlegend.jr, li.jr, ol.jr, p.jr, span.jr, sub.jr,\nsup.jr, table.jr, tbody.jr, td.jr, tfoot.jr,\nth.jr, thead.jr, tr.jr, u.jr, ul.jr {\n  border: 0;\n  -moz-box-sizing: border-box;\n  -webkit-box-sizing: border-box;\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n  vertical-align: baseline;\n}\n\nol.jr,\nul.jr,\nli.jr {\n  list-style: none;\n  list-style-image: none;\n}\n\ninput.jr[type=\"email\"],\ninput.jr[type=\"number\"],\ninput.jr[type=\"password\"],\ninput.jr[type=\"text\"] {\n  -moz-box-sizing: border-box;\n  -webkit-box-sizing: border-box;\n  box-sizing: border-box;\n}\n\ninput:-webkit-autofill {\n  -webkit-box-shadow: 0 0 0px 1000px white inset;\n}\n\ntable.jr {\n  border-collapse: collapse;\n  border-spacing: 0;\n}\n\na.jr {\n  background: transparent;\n}\n\narticle.jr,\naside.jr,\ndetails.jr,\nfigcaption.jr,\nfigure.jr,\nfooter.jr,\nheader.jr,\nhgroup.jr,\nmain.jr,\nnav.jr,\nsection.jr,\nsummary.jr {\n  border: 0;\n  display: block;\n  -moz-box-sizing: border-box;\n  -webkit-box-sizing: border-box;\n  box-sizing: border-box;\n  font-family: inherit;\n  margin: 0;\n  padding: 0;\n}\n\nbutton.jr,\ninput.jr,\noptgroup.jr,\nselect.jr,\ntextarea.jr {\n  color: inherit;\n  font: inherit;\n  margin: 0;\n}\n\nbutton.jr {\n  overflow: visible;\n}\n\nbutton.jr,\nselect.jr {\n  text-transform: none;\n}\n\nbutton.jr,\nhtml input.jr[type=\"button\"],\ninput.jr[type=\"reset\"],\ninput.jr[type=\"submit\"] {\n  -webkit-appearance: button;\n  cursor: pointer;\n}\n\nbutton.jr[disabled],\nhtml input.jr[disabled] {\n  cursor: default;\n}\n\nbutton.jr::-moz-focus-inner,\ninput.jr::-moz-focus-inner {\n  border: 0;\n  padding: 0;\n}\n\ninput.jr {\n  line-height: normal;\n}\n\ninput.jr[type=\"checkbox\"],\ninput.jr[type=\"radio\"] {\n  box-sizing: border-box;\n  padding: 0;\n}\n\ninput.jr[type=\"number\"]::-webkit-inner-spin-