 0 1 auto;\n}\n\n.jr-mJointree-join-actionDropdown.jr {\n  width: 44px;\n}\n\n.jr-mJointree-expression.jr {\n  align-content: space-between;\n  display: flex;\n  flex-direction: row;\n  flex-wrap: nowrap;\n  min-height: 32px;\n  padding-left: 22px;\n  padding-right: 12px;\n}\n\n.jr-mJointree-expression.jr:last-child {\n  border-bottom-left-radius: 5px;\n  border-bottom-right-radius: 5px;\n}\n\n.jr-mJointree-expression-field.jr {\n  align-self: center;\n  font-size: 13px;\n  line-height: 1.5;\n  overflow: hidden;\n  padding-left: 14px;\n  padding-right: 14px;\n  text-align: left;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.jr-mJointree-expression-fieldLeft.jr {\n  flex: 1 1 20%;\n  min-width: 200px;\n}\n\n.jr-mJointree-expression-field-table.jr {\n  color: #707070;\n}\n\n.jr-mJointree-expression-operator.jr {\n  align-self: center;\n  flex: 1 1 10%;\n  padding-left: 6px;\n  padding-right: 6px;\n}\n\n.jr-mJointree-expression-fieldRight.jr {\n  flex: 2 2 40%;\n}\n\n.jr-mJointree-expression-fieldCustom.jr {\n  flex: 2 2 calc(40% - 32px);\n}\n\n.jr-mJointree-expression-fieldComplex.jr {\n  align-self: flex-start;\n  flex: 1 1 20%;\n  min-width: 200px;\n  padding-top: 8px;\n  padding-bottom: 8px;\n  white-space: normal;\n}\n\n.jr-mJointree-expression-action.jr {\n  align-self: center;\n}\n\n.jr-mJointree-expression-actionDropdown.jr {\n  width: 44px;\n}\n\n.jr-mJointree-dropzones.jr {\n  align-content: space-between;\n  border-bottom: none;\n  border-bottom-left-radius: 5px;\n  border-bottom-right-radius: 5px;\n  display: flex;\n  flex-direction: row;\n  flex-wrap: nowrap;\n  height: auto;\n  padding: 6px;\n}\n\n.jr-mJointree-dropzones-dropzone.jr {\n  flex: 0 1 58%;\n}\n\n.jr-mJointree-dropzones-joiner.jr {\n  align-self: center;\n  flex: 0 0 auto;\n  margin: 0 12px;\n  opacity: .75;\n}\n\n.jr-mJointree-footer.jr {\n  background-color: #fff;\n  border-radius: 0 0 5px 5px;\n  border-top: none;\n  height: 6px;\n}\n\n.jr-mJointree.jr-isHovered.jr {\n  border: